}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheet';

/** A person's plan: a DRAFT claim of `amount` on every plan date, `start` then every `every` days, up to
 *  `end` (yyyy-MM-dd); `generated` is how many claims it has made so far. */
export type Plan = { id: number; personId: number; amount: string; start: string; every: number; end: string; generated: number };

/** Under the sheet's key, so loading the sheet again re-reads its plans. */
export const plansKey = (sheet: string) => [...sheetKey(sheet), 'plans'] as const;

export function usePlans(sheet: string) {
  return useQuery({
    queryKey: plansKey(sheet),
    queryFn: () => getJson<Plan[]>(`/api/sheets/${encodeURIComponent(sheet)}/plans`),
    enabled: sheet !== '',
  });
}
import { type ChangeEvent, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, peopleKey, personActionKey, useLatestPersonAction } from '../people/people';
import { claimsKey } from '../claims/claims';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { type Plan, plansKey, usePlans } from './plans';

type Fields = { amount: string; start: string; every: string; end: string };
const EMPTY: Fields = { amount: '', start: '', every: '', end: '' };

function PlansHead() {
  return <th>Plans</th>;
}

// The person's plans, each with how many claims it has made so far, and the form that adds one. A bad
// amount or interval, or an end before the start, is refused with an error on the row until the form is
// changed or the next action on the row is taken.
function PersonPlans({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const plans = usePlans(sheet);
  const [fields, setFields] = useState<Fields>(EMPTY);
  const queryClient = useQueryClient();

  const add = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: (f: Fields) =>
      postJson<Plan>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/plans`, { ...f, user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: plansKey(sheet) });
      setFields(EMPTY);
    },
  });
